    }
    if (error && typeof error === 'object' && 'status' in error && typeof error.status === 'number' && error.status < 500) {
      return ctx.response.status(error.status).send({ errors: { body: ['is invalid'] } })
    }
    return super.handle(error, ctx)
  }
